'use strict';
window.editsScene=function(stage){
 const common='<p class="edits-kicker">CONSUMERGENEDIT · EMNLP 2026</p>';
 if(stage===0)return common+`<div class="edit-demo"><div class="edit-compare"><img src="assets/example-000.jpg" alt="Source photograph: a hummingbird beside a red flower"><img class="compare-after" src="assets/example-001.jpg" alt="Consumer-edited photograph with the bird removed"><span class="compare-divider"></span></div><div class="compare-labels"><span>Source</span><span id="edit-kind">Object removal</span></div><label class="range-label">Reveal the edit <input id="edit-reveal" type="range" min="0" max="100" value="50" aria-label="Reveal edited image percentage"></label><div class="edit-options"><button data-example="1" aria-pressed="true">Removal</button><button data-example="2" aria-pressed="false">Generated content</button></div><p class="edits-note">Actual examples supplied with the paper. The slider compares images; it is not a live detector.</p></div>`;
 if(stage===1)return common+`<div class="pipeline"><div><b>4,000</b><span>source images</span><small>32 scene categories</small></div><i>→</i><div><b>48,000</b><span>consumer edits</span><small>Apple · Google · Samsung</small></div><i>→</i><div><b>144,000</b><span>compressed variants</span><small>Three quality levels</small></div></div><div class="task-grid"><span>Was it edited?</span><span>What changed?</span><span>Where did it change?</span><span>Does language matter?</span></div><p class="edits-note">English · Bangla · Persian/Farsi. Five captioning VLMs; a separate five-model detection benchmark. Caption analysis covers 2,000 source, 24,000 edited and 72,000 compressed images.</p><details class="paper-figure"><summary>View the paper’s full benchmark diagram</summary><img src="assets/overall.png" alt="Original five-stage paper diagram: source images, consumer editing, metadata and compression, multilingual annotation, benchmark tasks"></details>`;
 return common+`<div class="language-results"><div class="edit-options"><button data-language="0" aria-pressed="true">Bangla</button><button data-language="1" aria-pressed="false">Persian / Farsi</button></div><p>Agreement with English on the primary edit type</p><div id="agreement-bars"></div><p class="edits-note">Figure 3: agreement is not accuracy. A model can repeat the same mistake across languages. Human-reference full-correctness remained below 40% for every language’s best model.</p><details class="paper-figure"><summary>View multilingual and compression results</summary><img src="assets/multilingual-figure.png" alt="Paper Figure 3: caption similarity, visual grounding, CIDEr, length ratio and cross-language agreement across five VLMs and compression levels"></details></div>`;
};
window.bindEditsScene=function(stage,scene,pause){
 const range=scene.querySelector('#edit-reveal');if(range){scene.style.setProperty('--reveal','50%');range.addEventListener('input',()=>{pause();scene.style.setProperty('--reveal',(100-Number(range.value))+'%')});scene.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{pause();scene.querySelector('.compare-after').src='assets/example-00'+b.dataset.example+'.jpg';scene.querySelector('.compare-after').alt=b.dataset.example==='1'?'Edited photograph with bird removed':'Edited photograph with generated butterfly';scene.querySelector('#edit-kind').textContent=b.dataset.example==='1'?'Object removal':'Generated content';scene.querySelectorAll('[data-example]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}))}
 const bars=scene.querySelector('#agreement-bars');if(bars){const models=['LLaVA-OV 7B','Pixtral 12B','Phi-4-RV 15B','Gemma 3 27B','Qwen3-VL 32B'],values=[[27,42,40,50,71],[28,42,56,53,74]];function chart(lang){bars.innerHTML=models.map((m,i)=>`<div class="agreement-row"><span>${m}</span><div class="bar-track"><div style="width:${values[lang][i]}%"></div></div><b>${values[lang][i]}%</b></div>`).join('')};chart(0);scene.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{pause();chart(Number(b.dataset.language));scene.querySelectorAll('[data-language]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}))}
 scene.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)pause()}));
};
